// fetch() asks a web server for data. This is the USGS's public feed of every
// earthquake of magnitude 2.5 or more in the past 7 days.
const url = 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/2.5_week.geojson';

let feed;
try {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`the server answered ${response.status}`);
  feed = await response.json();
} catch (error) {
  // Live data can fail: no internet, a busy server, or a site that doesn't allow browser requests.
  throw new Error(`Couldn't fetch the earthquake feed (${error.message}). Check your connection and run this cell again.`);
}

// Keep only the fields we need, as plain numbers and text.
const quakes = feed.features
  .filter((f) => f.properties.mag !== null)
  .map((f) => ({
    mag: f.properties.mag,
    place: f.properties.place ?? 'Unknown',
    time: f.properties.time,              // milliseconds since 1 January 1970
    lon: f.geometry.coordinates[0],
    lat: f.geometry.coordinates[1],
    depth: f.geometry.coordinates[2],     // km below the surface
  }));

nb.set('quakes', quakes);
return `Fetched ${quakes.length} earthquakes. The USGS last updated this feed at ${new Date(feed.metadata.generated).toLocaleString()}.`;

// Vega-Lite can place points by longitude and latitude on a world projection.
const points = nb.get('map_points') ?? [];

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  title: {
    text: `A week of earthquakes: ${points.length} of them`,
    subtitle: 'There is no map underneath. The dots trace the edges of the tectonic plates by themselves.',
  },
  width: 720,
  height: 370,
  projection: { type: 'equalEarth' },
  layer: [
    { data: { sphere: true }, mark: { type: 'geoshape', fill: '#0b1d33' } },
    { data: { graticule: { step: [30, 30] } }, mark: { type: 'geoshape', filled: false, stroke: '#24476e', strokeWidth: 0.5 } },
    {
      data: { values: points },
      mark: { type: 'circle', opacity: 0.8, stroke: '#0b1d33', strokeWidth: 0.5 },
      encoding: {
        longitude: { field: 'lon', type: 'quantitative' },
        latitude: { field: 'lat', type: 'quantitative' },
        size: { field: 'mag', type: 'quantitative', title: 'Magnitude', scale: { domain: [2.5, 7], range: [6, 420] } },
        color: {
          field: 'depth_class', type: 'nominal', title: 'Started',
          scale: { domain: ['Shallow (under 70 km)', 'Middle (70 to 300 km)', 'Deep (over 300 km)'], range: ['#fbbf24', '#f97316', '#e11d48'] },
        },
        tooltip: [
          { field: 'place', title: 'Where' },
          { field: 'mag', title: 'Magnitude' },
          { field: 'depth', title: 'Depth (km)', format: '.0f' },
          { field: 'when', title: 'When' },
        ],
      },
    },
  ],
};

// Two charts side by side: hconcat puts charts in a row.
const bands = nb.get('bands') ?? [];
const regions = nb.get('regions') ?? [];

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  hconcat: [
    {
      title: 'How strong?',
      width: 250,
      height: 210,
      data: { values: bands },
      mark: { type: 'bar', cornerRadiusEnd: 3, color: '#f97316' },
      encoding: {
        x: { field: 'band', type: 'ordinal', sort: null, title: 'Magnitude', axis: { labelAngle: 0 } },
        y: { field: 'count', type: 'quantitative', title: 'Earthquakes' },
        tooltip: [{ field: 'band', title: 'Magnitude' }, { field: 'count', title: 'Earthquakes' }],
      },
    },
    {
      title: 'Busiest regions',
      width: 280,
      height: 210,
      data: { values: regions },
      mark: { type: 'bar', cornerRadiusEnd: 3, color: '#0ea5e9' },
      encoding: {
        y: { field: 'region', type: 'nominal', sort: '-x', title: null },
        x: { field: 'count', type: 'quantitative', title: 'Earthquakes' },
        tooltip: [{ field: 'region', title: 'Region' }, { field: 'count', title: 'Earthquakes' }],
      },
    },
  ],
};

// The five strongest, as an HTML table. It sets its own colours (tutorial 03's habit)
// and escapes the place names, which come from someone else's server.
const strongest = nb.get('strongest') ?? [];
const esc = (text) => String(text).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);

function ago(ms) {
  const hours = Math.round((Date.now() - ms) / 3600000);
  if (hours < 1) return 'within the hour';
  return hours < 48 ? `${hours} hours ago` : `${Math.round(hours / 24)} days ago`;
}
const badge = (mag) => (mag >= 6 ? '#e11d48' : mag >= 5 ? '#f97316' : '#ca8a04');

const rows = strongest.map((q) => `
  <tr>
    <td><span class="mag" style="background:${badge(q.mag)}">${q.mag.toFixed(1)}</span></td>
    <td class="place">${esc(q.place)}</td>
    <td class="dim">${Math.round(q.depth)} km down</td>
    <td class="dim">${ago(q.time)}</td>
  </tr>`).join('');

return `
<style>
  .card { background: #0f172a; color: #e2e8f0; font: 14px/1.5 system-ui, sans-serif; border-radius: 12px; padding: 14px 18px; }
  h3 { margin: 0 0 8px; font-size: 15px; color: #f8fafc; }
  table { width: 100%; border-collapse: collapse; }
  td { padding: 6px 14px 6px 0; border-top: 1px solid #1e293b; }
  .mag { display: inline-block; min-width: 34px; text-align: center; color: #fff; font-weight: 700; border-radius: 999px; padding: 1px 8px; }
  .place { width: 100%; }
  .dim { color: #94a3b8; white-space: nowrap; }
  .foot { color: #64748b; font-size: 12px; margin-top: 8px; }
</style>
<div class="card">
  <h3>The five strongest this week</h3>
  <table>${rows}</table>
  <div class="foot">Source: USGS. Each step up in magnitude means about 32 times more energy released.</div>
</div>`;
